package com.ecommerce.recommendation.repo;import com.ecommerce.common.ServiceClient;import com.ecommerce.recommendation.model.Customer;import java.util.*;
@org.springframework.stereotype.Component public class CustomerRepository {private final ServiceClient http;public CustomerRepository(ServiceClient h){http=h;}public List<Customer> findAll(){return Arrays.asList(http.get("http://auth-service/internal/customers",Customer[].class).orElseThrow());}public Optional<Customer> findById(Long id){return http.get("http://auth-service/internal/customers/"+id,Customer.class);}public long count(){return findAll().size();}}